  const [consumerDrawerOpen, setConsumerDrawerOpen] = useState<boolean>(false);
  const [rawModalOpen, setRawModalOpen] = useState<boolean>(false);

  // Fetch overview from CMS backend (which proxies /varz, /jsz, /connz)
  const {
    data,
    isLoading,
    isFetching,
    error,
    refetch,
    dataUpdatedAt,
  } = useQuery<NatsOverviewResponse>({
    queryKey: ['nats-overview'],
    queryFn: async () => {
      const resp = await cmsApi.get<NatsOverviewResponse>('/api/system/nats/overview');
      return resp.data;
    },
    refetchInterval: pollInterval > 0 ? pollInterval : false,
    staleTime: 3000,
  });

